onClick={(e) => {
            const r = e.currentTarget.getBoundingClientRect()
            const d = Math.floor((e.clientX - r.left - L) / cw)
            const hr = Math.floor((e.clientY - r.top - T) / RH)
            if (d >= 0 && d < days && hr >= 0 && hr < 24) moveTo(startMs + d * DAY + hr * HOUR, startMs)
          }}

handler.setInputAction((e: ScreenSpaceEventHandler.PositionedEvent) => {
      const picked = viewer.scene.pick(e.position) as { id?: Entity } | undefined
      for (const [id, ent] of markerEntities.current) {
        if (picked?.id === ent) {
          handlers.current.onPickMarker(id)
          return
        }
      }
      const p = pick(e.position)
      if (!p) return
      const round = (v: number) => Math.round(v * 1e4) / 1e4
      handlers.current.onPickPoint({ latDeg: round(p.latDeg), lonEastDeg: round(p.lonEastDeg) })
    }, ScreenSpaceEventType.LEFT_CLICK)

handler.setInputAction((e: ScreenSpaceEventHandler.MotionEvent) => {
      const p = pick(e.endPosition)
      handlers.current.onHover?.(p ? `${formatLat(p.latDeg, 2)}  ${formatLon(p.lonEastDeg, 2)}` : '')
    }, ScreenSpaceEventType.MOUSE_MOVE)

onChange={(e) => {
              const site = EXAMPLE_SITES.find((s) => s.id === e.target.value)
              if (site) setScenarioInput('B', { site: { latDeg: site.latDeg, lonEastDeg: site.lonEastDeg }, siteName: site.name })
            }}

onChange={(e) => {
            const v = Number(e.target.value)
            if (Number.isFinite(v) && v >= 0 && v <= 500) setScenarioInput('A', { observerHeightM: v })
          }}

onChange={(e) => {
              const r = all.find((x) => x.id === e.target.value)
              if (r) onPick({ ...r.center, name: r.name })
            }}

provider.submitTerrainAnalysis(
          {
            site: input.site,
            observerHeightM: input.observerHeightM,
            config: { azimuthStepDeg: s.azimuthStepDeg, maxDistanceKm: s.maxDistanceKm },
          },
          signal,
        )

provider.submitScenarioEvaluation(
          {
            terrainAnalysisId: terrain.id,
            startUtc: new Date(input.startMs).toISOString(),
            stopUtc: new Date(stopMs).toISOString(),
            stepMinutes: s.stepMinutes,
          },
          signal,
        )

provider.submitScenarioEvaluation(
          {
            terrainAnalysisId: terrain.id,
            startUtc: new Date(input.startMs - s.durationDays * 86_400_000).toISOString(),
            stopUtc: new Date(input.startMs).toISOString(),
            stepMinutes: s.stepMinutes,
          },
          signal,
        )
